function afterRoute(){document.querySelectorAll("[data-to]").forEach(el=>{const to=+el.dataset.to,pre=el.dataset.pre||"",suf=el.dataset.suf||"",fmt=v=>pre+Math.round(v)+suf;if(RM||!("IntersectionObserver" in window)){el.textContent=fmt(to);return}el.textContent=fmt(0);const o=new IntersectionObserver(es=>{if(es[0].isIntersecting){o.disconnect();const t0=performance.now(),st=t=>{const p=Math.min(1,(t-t0)/1300),e=1-Math.pow(1-p,3);el.textContent=fmt(to*e);if(p<1)requestAnimationFrame(st)};requestAnimationFrame(st)}});o.observe(el)})}
const RM=matchMedia("(prefers-reduced-motion:reduce)").matches;let io=null,first=true;
if(!RM&&"IntersectionObserver" in window){document.documentElement.classList.add("rvon");io=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.classList.add("in");io.unobserve(x.target)}}),{rootMargin:"0px 0px -8% 0px"})}
const reveal=()=>document.querySelectorAll("#app .card,#app .tl>div").forEach(el=>{el.classList.add("rv");io?io.observe(el):el.classList.add("in")});
const setLD=o=>{let s=document.getElementById("ld");if(!s){s=document.createElement("script");s.type="application/ld+json";s.id="ld";document.head.appendChild(s)}s.textContent=o?JSON.stringify(o):""};
