const cbt=$("cbt"),cbp=$("cbp"),cbl=$("cbl"),cbq=$("cbq"),cbf=$("cbf"),cbi=$("cbi");let greeted=false,last="";
const TRM={plumbing:/plumb|drain|pipe/,hvac:/hvac|heating|air.?condition|\bac\b|furnace|cooling/,roofing:/roof/,concrete:/concrete|driveway|patio|slab/,restoration:/restor|water damage|mold|fire damage|flood/,electrical:/electric/,landscaping:/landscap|lawn|garden/,pestcontrol:/pest|termite|exterminat|rodent/,garagedoors:/garage|opener/,cleaning:/clean|maid|janitor|housekeep|window wash/,cardetailing:/detailing|car wash|ceramic coat|paint correction|\bcar\b|vehicle/};
