const L=(h,t)=>`<br><a href="${h}">${t}</a>`;
const INT=[
{n:"valid",w:5,re:[/\bvalid\b/,/\bqualif(y|ied|ies|ication)\b/,/what counts/,/what is (a|an) (good )?(lead|call)/,/what (is|are) (a )?lead/],a:()=>"A valid lead is a real person inside your service area asking for your trade, on a call that lasts at least 30 seconds and is not a repeat of the same caller within 30 days. You are billed for valid calls only."+L("/how/","See the full process")},
{n:"invalid",w:5,re:[/\binvalid\b/,/not valid/,/bad (lead|call)/,/junk|spam|robocall|duplicate|wrong number|out of area|outside (my|the) area/,/credit|refund|dispute|money back/],a:()=>"Calls under 30 seconds, outside your service area, or a repeat of the same caller within 30 days are credited automatically. Anything else, like a wrong trade or spam, you can dispute within 72 hours by replying with the call ID. We review it and credit valid disputes within 2 business days."},
{n:"billing",w:4,re:[/invoice|billing|billed|\bbill\b|charge|payment|\bpay\b|card on file|when do (i|we) pay|how do (i|we) pay/],a:()=>"Pay-per-call accounts get a weekly invoice by email with a call-by-call breakdown, charged to the card on file. Monthly plans are billed upfront each month. Calls above plan volume appear on the next invoice. You are billed for valid calls only."},
{n:"report",w:4,re:[/report|dashboard|call log|tracking|see (my|the|what) (calls|results|i paid)|statistics|stats/],a:()=>"We email a report every week with your calls, sources, outcomes and credits, and the call log is attached."},
{n:"price",w:4,re:[/price|pricing|\bcost|how much|\bfees?\b|expensive|cheap|\brates?\b|\bplans?\b|per (call|lead)|afford/],a:t=>{const k=tradeIn(t);return k?`${TR[k][0]} calls start at $${PC[k]} per valid call. Monthly plans run $595 (about 15 calls), $1,095 (about 28 calls) or $1,795 (about 50 calls). No setup fees.`+L("/pricing/","See all pricing"):"Pay per valid call from $39 to $89 depending on trade, or choose a monthly plan: $595 (about 15 calls), $1,095 (about 28) or $1,795 (about 50). No setup fees and no contracts."+L("/pricing/","See all pricing")}},
{n:"contract",w:4,re:[/contract|cancel|commit|lock.?in|notice|pause|terminate|minimum|quit|stop (the )?service/],a:()=>"No contracts and no setup fees. Pause or stop any time with 7 days notice."},
{n:"exclusive",w:4,re:[/exclusive|shared|\bshare\b|resell|resold|other (contractors|businesses|companies)|competition|who (gets|receives|sees)/],a:()=>"Every call goes to one business only. We never resell or share a call."+L("/blog/sharedvsexclusive/","Read: shared vs exclusive leads")},
{n:"volume",w:5,re:[/how many (calls|leads)/,/\bvolume\b/,/calls? (a|per) month/,/leads? (a|per) month/],a:()=>"Our clients average 28 calls a month. Volume depends on your trade and area, and you can raise or lower it with short notice."},
{n:"appt",w:5,re:[/appointment/,/book(ed|ing)? rate/,/close rate/],a:()=>"Our clients book about 73% of their calls into appointments on average. Results vary with how fast and how well calls are answered."},
{n:"roi",w:4,re:[/\broi\b/,/result|revenue|return on|proof|case stud|success|\b8x\b|how well/],a:()=>"Our clients average 8x ROI, 28 calls a month and a 73% appointment rate on calls. Results vary and nothing is guaranteed."+L("/results/","See results")},
{n:"guarantee",w:6,re:[/guarantee|promise|risk|certain|for sure/],a:()=>"We can't guarantee jobs or revenue, and nobody honest can. What we do commit to: exclusive calls, published prices, valid-calls-only billing and no contracts."},
{n:"speed",w:5,re:[/how (fast|quick|soon|long)/,/when (will|do|can).*(start|get|begin|receive)/,/timeline|first calls?|get started in/],a:()=>"Timing depends on your trade and area. Many clients see their first calls within days of launch. We confirm timing on your call."},
{n:"how",w:3,re:[/how (does|do|is) (it|this|that|the)/,/how.*work/,/process|onboard|steps|sign ?up|get started|begin|launch/],a:()=>"We talk for 15 minutes, map your area and services, launch your campaign, screen every call and ring your phone with exclusive calls. You get a weekly report and bill for valid calls only."+L("/how/","See how it works")},
{n:"trades",w:4,re:[/which trades/,/what trades/,/trades?.*(serve|cover|work)/,/industries|do you (serve|work with|cover|do)/,/what (services|do you)/],a:()=>"We serve plumbing, HVAC, roofing, concrete, restoration, electrical, landscaping, pest control, garage doors, cleaning and car detailing."+L("/trades/","See trades")},
{n:"tradeinfo",w:2,re:[/plumb|hvac|heating|roof|concrete|restor|electric|landscap|pest|garage|clean|maid|detail|car wash/],a:t=>{const k=tradeIn(t);return k?`Yes, we serve ${TR[k][0].toLowerCase()} businesses. Calls start at $${PC[k]}.`+L("/trade/"+k+"/","See the "+TR[k][0]+" page"):"We serve eleven trades."+L("/trades/","See trades")}},
{n:"area",w:3,re:[/\barea\b|\bzip\b|\bcity\b|territory|radius|coverage|\bcover\b|\bwhere\b|\bstate\b|region|nationwide/],a:()=>"Tell us your city or ZIP and we confirm coverage on your call. We verify the caller is inside your service area before it counts as billable."},
{n:"compare",w:4,re:[/servicedirect|service direct|angi|homeadvisor|thumbtack|compare|competitor|different|better than|why (you|choose|should)/],a:()=>"Published prices, exclusive calls, valid-calls-only billing, rule-based credits and no contracts or setup fees. Most providers hide pricing and terms. We don't."+L("/pricing/","See the comparison")},
{n:"privacy",w:4,re:[/privacy|my data|\brecord|cookie|personal (data|info)/],a:()=>"Calls may be recorded for quality, billing and dispute review, and callers are told. We don't sell personal information."+L("/privacy/","Read the privacy policy")},
{n:"human",w:4,re:[/human|real person|someone|speak|talk|phone|call (you|us)|contact|\bbook\b|meeting|demo|sales|representative|agent|\bemail\b/],a:()=>"Happy to connect you with a person. Fill a short form, call us or book a meeting."+BTN},
{n:"about",w:4,re:[/who are you|what (is|does) (highservicedemand|hsd|your company|the company)|about (you|us)|what do you do/],a:()=>"HighServiceDemand delivers exclusive phone calls from homeowners to home-service businesses. Prices are published, billing is for valid calls only and there are no contracts."},
{n:"greet",w:5,re:[/^(hi|hello|hey|yo|good (morning|afternoon|evening))\b/],a:()=>"Hi! Ask about pricing, valid calls, billing, how it works or your trade."},
{n:"thanks",w:5,re:[/thank|thanks|cheers|appreciate/,/^(ok|okay|great|cool|awesome|perfect)\b/],a:()=>"You're welcome. Anything else?"+BTN}];
const guess=q=>{const t=q.toLowerCase().trim();let best=null,bs=0;INT.forEach(i=>{let s=0;i.re.forEach(r=>{if(r.test(t))s=Math.max(s,i.w)+(s?1:0)});if(s>bs){bs=s;best=i}});if(tradeIn(t)&&last==="price"&&(!best||best.n==="tradeinfo"))best=INT.find(i=>i.n==="price");if(best&&best.n==="trades"&&tradeIn(t))best=INT.find(i=>i.n==="tradeinfo");return best};
window.hsdIntent=q=>{const g=guess(q);return g?g.n:null};
