const hreply=q=>{const t=q.toLowerCase().trim();const g=HI.find(i=>i.re.test(t));return g?g.a(t):"I am not sure about that one. I can help with services, cost, how it works, response times or the Best Job Guarantee, or you can talk to a person."+BTN3};const reply=q=>{if(document.body.dataset.mode==="home"){add(hreply(q),"b",1);return}const g=guess(q);if(!g){add("I'm an automated assistant and I'm not sure about that one. Try asking about pricing, valid calls, billing, how it works or your trade, or talk to a person."+BTN,"b",1);return}last=g.n;add(g.a(q.toLowerCase()),"b",1)};
